{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Cloud SQL database backup configuration disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The `backup_configuration` block explicitly sets `enabled = false`, which prevents automated backups and point-in-time recovery, risking data loss."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "SSL not required for Cloud SQL connections",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "The `require_ssl` flag is set to `false`, allowing unencrypted connections to the database, which exposes sensitive metadata in transit."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "PostgreSQL log_lock_waits flag disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "LOW",
      "explanation": "The `log_lock_waits` database flag is explicitly set to `off`, hindering the ability to diagnose performance issues related to lock contention."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = false\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n  }\n}",
  "fix_summary": "Enabled automated backups by setting `backup_configuration.enabled` to true. Enforced SSL encryption for all incoming connections by setting `ip_configuration.require_ssl` to true. Enabled lock wait logging by changing the `log_lock_waits` database flag value to 'on'."
}
